function testServerAddressNg() {
  const urlServerNg = jQuery('input[name="server_address_ng"]').val();

  jQuery.ajax({
    type : 'GET',
    url : `${urlServerNg}/centreon-map/api/latest/actuator/health`,
    success: () => {
      const icon = '<img src="./img/icons/checked.png" class="ico-16">';
      jQuery('.result_test_server_address_ng').html(`${icon} ${i18n.ConnectionTestSuccessful}`);
    }, 
    error: () => {
      const icon = '<img src="./img/icons/cross.png" class="ico-16">';
      jQuery('.result_test_server_address_ng').html(`${icon} ${i18n.ConnectionTestFailed}`);
    }
  });
}

function testInternalServerAddressNg() {
  const baseUrl = window.location.origin;
  const internalUrlServerNg = jQuery('input[name="internal_server_address_ng"]')
    .val();
  const data = { url: internalUrlServerNg };

  jQuery.ajax({
    type: 'POST',
    url: `${baseUrl}/centreon/api/latest/map/check-health`,
    dataType: 'json',
    contentType: 'application/json; charset=utf-8',
    data: JSON.stringify(data),
    success: () => {
      const icon = '<img src="./img/icons/checked.png" class="ico-16">';
      jQuery('.result_test_internal_server_address_ng')
        .html(`${icon} ${i18n.ConnectionTestSuccessful}`);
    },
    error: () => {
      const icon = '<img src="./img/icons/cross.png" class="ico-16">';
      jQuery('.result_test_internal_server_address_ng')
        .html(`${icon} ${i18n.ConnectionTestFailed}`);
    }
  });
}

/**
 * Management of inputs required or not for server addresses
 * via HTML 5 for the "required" before saving the form. 
 * @param {boolean} isNgSelected 
 */
function enableInputRequired(isNgSelected) {
  if (isNgSelected) {
    jQuery('input[name="server_address_ng"]').attr('required', true);
    jQuery('input[name="server_address"]').removeAttr('required');
  } else {
    jQuery('input[name="server_address_ng"]').removeAttr('required');
    jQuery('input[name="server_address"]').attr('required', true);
  }
}
